// 合约工具注册表（自动生成自 V1 explorer tools，2026-08-01）
// 地址来源: V1 scripts/misc/deployments.js + tools 配置
import type { Abi } from 'viem'

// ---------- pin 配置（合约工具“📌 重点关注”面板） ----------
// 可选字段：未配置 pins 的合约保持既有行为（向后兼容）

export type PinFormat =
  | 'raw'        // 默认：原样展示（bigint 转字符串）
  | 'number'     // 千分位数字
  | 'percent'    // 百分比（表达式产出 0-100，展示时保留 2 位小数 + %）
  | 'j'          // J 代币（按 18 位小数格式化，需 bigint 原始值）
  | 'address'    // 短地址 0x1234…abcd
  | 'timestamp'  // 秒时间戳 → YYYY-MM-DD HH:mm:ss
  | 'bool'       // true/false → ✅/❌
  | 'text'       // 字符串直接展示

export interface PinConfig {
  /** 显示名，同时是表达式引用名（$label） */
  label: string
  /** 调用的 view/pure 函数名；有 expr 时可不填（纯计算 pin） */
  fn?: string
  /** 函数参数表达式数组，可引用其他 pin（$label），如 ['$提案总数 - 1'] */
  args?: string[]
  /** 可选：计算表达式。缺省时直接展示函数返回值；可用 $v 引用当前返回值 */
  expr?: string
  /** 说明文字 */
  annotation?: string
  /** 展示格式（缺省 raw） */
  format?: PinFormat
  /** 可选：条件判断，表达式返回 true/false，分别显示 then/else（覆盖 format） */
  cond?: { expr: string; then: string; else: string }
}

export interface ToolboxContract {
  key: string
  name: string
  tag: string
  icon: string
  address: `0x${string}`
  abi: Abi
  category: 'core' | 'eco'
  /** 可选：打开页面时自动读取并展示的字段（📌 重点关注） */
  pins?: PinConfig[]
}

